# --------------------------------------------------------------------------
# offline --direct path: authority commands must fail closed, DB untouched
# --------------------------------------------------------------------------

def run_main(argv: list[str]) -> tuple[int, dict[str, Any], list[str]]:
    out = io.StringIO()
    with tempfile.TemporaryDirectory() as td:
        with redirect_stdout(out):
            code = researchctl.main(["--root", td, "--direct"] + argv)
        leftover = sorted(
            str(p.relative_to(td)) for p in Path(td).rglob("*")
        )
    payload = json.loads(out.getvalue())
    return code, payload, leftover


