# direct C/D routing
# --------------------------------------------------------------------------

@test
def direct_c_routed_to_store() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td) as patch:
        result = researchctld.dispatch(
            {
                "command": "amendment-register-direct",
                "amendment_id": "C",
                "amendment_sha256": AMENDMENT_C_SHA256,
                "producer_session_id": "producer-session",
            },
            peer_uid=9001,
            peer_pid=1234,
        )
        assert result == {"status": "PASS", "command": "register_amendment_direct"}
        db = FakeDB.instances[-1]
        assert db.root == Path(td)
        assert db.schema_checks == 1
        authority = FakeAuthority.instances[-1]
        assert authority.db_path == Path(td) / "research.sqlite"
        name, amendment_id, digest, producer, ctx = authority.calls[0]
        assert name == "register_amendment_direct"
        assert amendment_id == "C"
        assert digest == AMENDMENT_C_SHA256
        assert producer == "producer-session"
        assert isinstance(ctx, Ctx)
        assert ctx.peer_uid == 9001
        assert ctx.session_id == "session-1234"
        assert patch.context_calls == [(1234, 9001)]
        assert list(Path(td).rglob("*")) == []  # no DB file created


