@test
def direct_missing_or_invalid_fields_fail_closed() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        cases = [
            {"command": "amendment-register-direct"},  # all three missing
            {"command": "amendment-register-direct", "amendment_id": "C"},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": AMENDMENT_C_SHA256},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": "",
             "producer_session_id": "producer-session"},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": AMENDMENT_C_SHA256,
             "producer_session_id": None},
            {"command": "amendment-register-direct",
             "amendment_id": 7, "amendment_sha256": AMENDMENT_C_SHA256,
             "producer_session_id": "producer-session"},
        ]
        for request in cases:
            expect_fail_closed(
                "amendment-register-direct requires amendment_id, "
                "amendment_sha256, producer_session_id",
                lambda r=request: researchctld.dispatch(r, peer_uid=9001, peer_pid=1234),
            )
        assert FakeAuthority.instances[-1].calls == []


